<template>
	<view class="my-nav-header">
		<view class="status-bar"></view>
		<view class="home-nav" v-show="type=='home'">
			<view><text class="nav-text">{{enterprise.name}}</text></view>
			<view><text class="nav-text">{{userInfo.realName}}</text></view>
		</view>
		<view class="home-nav" v-show="type=='carNumber'">
			<view><text class="iconfont icon-fanhui car-text" @click="goBack"></text></view>
			<view><text class="nav-text">开单</text></view>
			<view @click="choseImage"><text class="iconfont icon-xiangji car-text"></text></view>
		</view>
		<view class="home-nav" v-show="type=='orderDetail'">
			<view><text class="iconfont icon-fanhui car-text" @click="goBack"></text></view>
			<view><text class="nav-text">{{title}}</text></view>
			<view>
				<!-- <text class="iconfont icon-sandian" style="color: #fff;font-size: 25px;"/> -->
			</view>
		</view>
		<view class="home-nav" v-show="type=='addConsumePro'">
			<view><text class="iconfont icon-fanhui car-text" @click="goBack"></text></view>
			<view><text class="nav-text">{{title}}</text></view>
			<view><text></text></view>
		</view>
	</view>

</template>

<script>
	import {
		pathToBase64
	} from "../../common/js/image_tools.js"
	export default {
		name: "nav-header",
		data() {
			return {
				userInfo: {},
				enterprise: {}
			};
		},
		computed: {

		},
		props: {
			type: {
				type: String,
				required: true
			},
			title: {
				type: String,
				required: true
			}
		},
		created() {
			this.userInfo = uni.getStorageSync("userInfo")
			this.enterprise = uni.getStorageSync("enterprise")
		},
		activated() {

		},
		methods: {
			goBack() {
				uni.navigateBack({
					delta: 1,
					animationType: "pop-out",
					animationDuration: 300
				});
			},
			choseImage() {
				
				const that = this
				uni.chooseImage({
					count: 1,
					sizeType: ['original', 'compressed'],
					sourceType: ['album','camera'],
					success: function(res) {
						// 预览图片
						const imagePath = res.tempFilePaths[0]
						console.log("imagePath====="+imagePath);
						pathToBase64(imagePath).then(base64=>{
							that.getOcrToken(base64)
						})
					
					}
				});

			},
			getOcrToken(base64Image) {
				console.log("base64Image====="+base64Image);
				uni.showLoading({
					title:"识别中。。。"
				})
				uni.request({
					url: 'https://aip.baidubce.com/oauth/2.0/token',
					method: 'POST',
					data: {
						'grant_type': 'client_credentials',
						'client_id': 'MhVAan70TGxg6eK39b8yl36i',
						'client_secret': '3wtGLvX3zwqhHxXALeAQf2TzNjDQnMMy'
					},
					header: {
						'Content-Type': 'application/x-www-form-urlencoded' //自定义请求头信息
					},
					success: (res) => {
						this.getOrcResult(res.data.access_token,base64Image)
						console.log(JSON.stringify(res));
					},
					fail:(err)=>{
						uni.showToast({
							title: "识别失败！",
							icon:'error',
							duration: 2000
						});
						uni.hideLoading()
					}

				})
			},
			getOrcResult(token,base64Image) {
				uni.request({
					url: 'https://aip.baidubce.com/rest/2.0/ocr/v1/license_plate?access_token=' + token,
					method: 'POST',
					data: {
						"image":base64Image
					},
					header: {
						'Content-Type': 'application/x-www-form-urlencoded' //自定义请求头信息
					},
					success: (res) => {
						uni.hideLoading()
						this.$emit("getCarNumber",res.data.words_result.number)
						console.log(JSON.stringify(res));

					},
					fail:(err) =>{
						uni.showToast({
							title: "识别失败！",
							icon:'error',
							duration: 2000
						});
						uni.hideLoading()
					}

				})
			}
		}
	}
</script>

<style lang="scss">
	@import url("../../common/css/icons.css");

	.my-nav-header {
		height: 80px;
		background-color: $uni-color-primary;
		.status-bar{
			height: 20px;
			background: white;
		}

		.home-nav {
			height: 100%;
			display: flex;
			justify-content: space-between;
			align-items: center;
			padding: 0 15px;
		}

		.nav-text {
			font-size: 16px;
			color: #fff;
		}

		.car-text {
			font-size: 24px;
			color: #fff;

		}

	}
</style>